body {
  font-family: 'Inter', sans-serif; /* Example web font */
  font-size: 1.125rem; /* Base font size */
  line-height: 1.6; /* Optimal unitless line height for readability */
  color: #333;
}

h1 {
  font-size: 3rem;
  line-height: 1.2; /* Tighter line height for headings */
  margin-bottom: 0.5em;
}

p {
  margin-bottom: 1em; /* Consistent spacing between paragraphs */
}
